xpath.script:
(function () {
    'use strict';
    // Redis SSE already applies current_bid / SOLD / UNSOLD. Keep this extra
    // Odoo poll only when the socket is off.
    if (window.AuctionChampSSE && window.AuctionChampSSE.enabled(document.documentElement)) {
        return;
    }
    setInterval(function () {
        if (typeof window._auctionLbPoll === 'function') {
            window._auctionLbPoll();
        }
    }, 2000);
})();
